#define STRICT_LIBRARY
#include "../four/strict.cpp"
constexpr int C3=41664,SZ=10*64*C3*2;
struct S{int k,b;array<int,3>x;int t;};
int tr[8][64],ci[64],cb[10],nt[64],tf[64][2],tp=Q;array<int,3> triple[C3];B bt[64][64];uint8_t al[64][64];
const int BAD=255,UN=254;vector<uint8_t> dd,rem5,reach5;vector<vector<U>> bins5(128);
int rank3(array<int,3>x){sort(x.begin(),x.end());return x[0]+x[1]*(x[1]-1)/2+x[2]*(x[2]-1)*(x[2]-2)/6;}
void init5(){int n=0;for(int y=0;y<4;y++)for(int x=0;x<=y;x++)cb[n++]=y*8+x;for(int p=0;p<64;p++){int x=p%8,y=p/8;for(int i=0;i<8;i++){int a=i&1?7-x:x,b=i&2?7-y:y;if(i&4)swap(a,b);tr[i][p]=8*b+a;}for(int i=0;i<8;i++)for(int j=0;j<10;j++)if(tr[i][p]==cb[j]){ci[p]=j;assert(nt[p]<2);tf[p][nt[p]++]=i;}}for(int c=2;c<64;c++)for(int b=1;b<c;b++)for(int a=0;a<b;a++)triple[rank3({a,b,c})]={a,b,c};for(int a=0;a<64;a++)for(int b=0;b<64;b++)if(a!=b){int x=b%8-a%8,y=b/8-a/8;bool r=!x||!y,d=abs(x)==abs(y);if(!r&&!d)continue;al[a][b]=r?1:2;int st=(x>0)-(x<0)+8*((y>0)-(y<0));for(int z=a+st;z!=b;z+=st)bt[a][b]|=bit(z);}}
inline U ix(S s){U best=UINT_MAX;for(int i=0;i<nt[s.b];i++){auto*m=tr[tf[s.b][i]];array<int,3>x={m[s.x[0]],m[s.x[1]],m[s.x[2]]};best=min(best,U(((ci[s.b]*64+m[s.k])*C3+rank3(x))*2+s.t));}return best;}
inline S de(U a){S s;s.t=a&1;a>>=1;s.x=triple[a%C3];a/=C3;s.k=a%64;s.b=cb[a/64];return s;}
inline B oc(S s){return bit(s.k)|bit(s.b)|bit(s.x[0])|bit(s.x[1])|bit(s.x[2]);}
inline bool at(S s,int q,B o,int skip=-1){if(king[s.k]&bit(q))return true;for(int i=0;i<3;i++)if(i!=skip){int p=s.x[i],a=al[p][q];if(a&&(tp==Q||a==1)&&!(bt[p][q]&o))return true;}return false;}
inline bool valid5(S s){B o=oc(s);return __builtin_popcountll(o)==5&&!(king[s.k]&bit(s.b))&&(s.t||!at(s,s.b,o));}
int lid;inline U lowerix(S s,int cap,int q){Pos p{};p.s[0]=s.k;p.s[1]=q;int n=2;for(int i=0;i<3;i++)if(i!=cap)p.s[n++]=s.x[i];return enc(ts[lid],p);}
inline void add5(U a,int d){assert(d<128);dd[a]=d;bins5[d].push_back(a);}
template<class F> void black5(S s,F f){B o=oc(s),opts=king[s.b]&~(king[s.k]|bit(s.k));while(opts){int q=__builtin_ctzll(opts);opts&=opts-1;int cap=-1;for(int i=0;i<3;i++)if(s.x[i]==q)cap=i;if(at(s,q,(o&~bit(s.b))|bit(q),cap))continue;if(cap>=0)f(true,lowerix(s,cap,q));else{S v=s;v.b=q;v.t=0;f(false,ix(v));}}}
template<class F> void white5(S s,F f){B o=oc(s),opts=king[s.k]&~(o|king[s.b]);while(opts){int q=__builtin_ctzll(opts);opts&=opts-1;S v=s;v.k=q;v.t=1;f(ix(v));}for(int i=0;i<3;i++)for(int d=0;d<(tp==Q?8:4);d++)for(int j=0;ray[s.x[i]][d][j]>=0;j++){int q=ray[s.x[i]][d][j];if(o&bit(q))break;S v=s;v.x[i]=q;v.t=1;f(ix(v));}}
template<class F> void pre5(S s,F f){B o=oc(s);if(!s.t){B b=king[s.b]&~(o|king[s.k]);while(b){int q=__builtin_ctzll(b);b&=b-1;S v=s;v.b=q;v.t=1;f(ix(v));}}else{B b=king[s.k]&~(o|king[s.b]);while(b){int q=__builtin_ctzll(b);b&=b-1;S v=s;v.k=q;v.t=0;if(!at(v,v.b,(o&~bit(s.k))|bit(q)))f(ix(v));}for(int i=0;i<3;i++)for(int d=0;d<(tp==Q?8:4);d++)for(int j=0;ray[s.x[i]][d][j]>=0;j++){int q=ray[s.x[i]][d][j];if(o&bit(q))break;S v=s;v.x[i]=q;v.t=0;if(!at(v,v.b,(o&~bit(s.x[i]))|bit(q)))f(ix(v));}}}
string fen5(S s){string z(64,' ');z[s.k]='K';z[s.b]='k';for(int q:s.x)z[q]=tp==Q?'Q':'R';string o;for(int y=7;y>=0;y--){int n=0;for(int x=0;x<8;x++){char c=z[y*8+x];if(c==' ')n++;else{if(n)o+=char('0'+n),n=0;o+=c;}}if(n)o+=char('0'+n);if(y)o+='/';}return o+(s.t?" b - - 0 1":" w - - 0 1");}
int main(int argc,char**argv){tp=argc>1&&string(argv[1])=="R"?R:Q;init();setup();auto cwd=filesystem::current_path();filesystem::current_path("../four");load();loadD();filesystem::current_path(cwd);lid=ids[tp][tp][0];auto&lt=ts[lid];auto&ld=ds[lid];init5();dd.assign(SZ,BAD);rem5.resize(SZ);vector<uint8_t> mx(SZ);long long validn[2]={};
for(U a=0;a<SZ;a++){S s=de(a);if(!valid5(s)||ix(s)!=a)continue;validn[s.t]++;dd[a]=UN;if(!s.t)continue;U seen[8];int n=0,ct=0,lo=-1;bool draw=false;black5(s,[&](bool cap,U b){ct++;if(cap){assert(lt.v[b]!=INV);if(lt.v[b]!=1)draw=true;else lo=max(lo,int(ld[b])+1);}else if(find(seen,seen+n,b)==seen+n)seen[n++]=b;});if(!ct){if(at(s,s.b,oc(s)))add5(a,0);continue;}if(draw)continue;rem5[a]=n;mx[a]=max(0,lo);if(!n)add5(a,lo);}
cerr<<"init "<<validn[0]<<' '<<validn[1]<<endl;
for(int d=0;d<128;d++){for(U a:bins5[d]){if(dd[a]!=d)continue;S s=de(a);U seen[8];int n=0;pre5(s,[&](U b){assert(dd[b]!=BAD);if(dd[b]!=UN)return;if(!s.t){if(!rem5[b]||find(seen,seen+n,b)!=seen+n)return;seen[n++]=b;mx[b]=max(mx[b],(uint8_t)(d+1));if(--rem5[b]==0)add5(b,mx[b]);}else add5(b,d+1);});}if(bins5[d].size())cerr<<"d "<<d<<" n "<<bins5[d].size()<<endl;}
vector<uint8_t> lr(lt.sz);vector<vector<U>> lb(128);for(U a=0;a<(U)lt.sz;a++)if(lt.v[a]==1)lb[ld[a]].push_back(a);for(int d=1;d<128;d++)for(U a:lb[d]){Pos p=dec(lt,a);moves(lt,p,[&](Move m,Pos v){auto[j,q]=child(lt,p,m,v);U b=enc(ts[j],q);if(ts[j].v[b]==1&&ds[j][b]==d-1&&(j!=lid||lr[b]))lr[a]=1;});}
reach5.assign(SZ,0);long long counts[2][256]={},nr[2][2]={},err=0,edges=0;int maxd[2]={};U ex[2]={};for(int d=1;d<128;d++)for(U a:bins5[d])if(dd[a]==d){S s=de(a);int f=0;if(s.t)black5(s,[&](bool c,U b){if(c){if(lt.v[b]==1&&ld[b]==d-1){f|=1;if(lr[b])f|=2;}}else if(dd[b]==d-1)f|=reach5[b];});else white5(s,[&](U b){if(dd[b]==d-1)f|=reach5[b];});reach5[a]=f;}
string nm=tp==Q?"KQQQvK":"KRRRvK";ofstream hist(nm+"_hist.tsv"),o(nm+"_stats.tsv"),w(nm+"_examples.tsv");bool ew[2][2]={};for(U a=0;a<SZ;a++){if(dd[a]==BAD)continue;S s=de(a);int d=dd[a];counts[s.t][d]++;if(d<UN){if(d>maxd[s.t])maxd[s.t]=d,ex[s.t]=a;for(int i=0;i<2;i++)if(reach5[a]&(1<<i)){nr[s.t][i]++;if(!ew[s.t][i])ew[s.t][i]=true,w<<s.t<<'\t'<<(4-i)<<'\t'<<d<<'\t'<<fen5(s)<<'\n';}}int best=UN,worst=-1,ct=0;bool draw=false;if(s.t){black5(s,[&](bool c,U b){int x=c?(lt.v[b]==1?ld[b]:UN):dd[b];assert(x!=BAD);ct++;edges++;if(x==UN)draw=true;else worst=max(worst,x+1);});int want=!ct?(at(s,s.b,oc(s))?0:UN):draw?UN:worst;if(want!=d){if(err<5)cerr<<"bad "<<fen5(s)<<' '<<d<<' '<<want<<endl;err++;}}else{white5(s,[&](U b){assert(dd[b]!=BAD);ct++;edges++;if(dd[b]!=UN)best=min(best,int(dd[b])+1);});if(best!=d){if(err<5)cerr<<"bad "<<fen5(s)<<' '<<d<<' '<<best<<endl;err++;}}}
o<<"material\tturn\tvalid\twins\tdraws\tmax_dtm\treach_4\treach_3\tmax_fen\n";for(int t=0;t<2;t++){long long wins=0;for(int d=0;d<UN;d++)wins+=counts[t][d];o<<nm<<'\t'<<t<<'\t'<<validn[t]<<'\t'<<wins<<'\t'<<counts[t][UN]<<'\t'<<maxd[t]<<'\t'<<nr[t][0]<<'\t'<<nr[t][1]<<'\t'<<fen5(de(ex[t]))<<'\n';for(int d=0;d<256;d++)if(counts[t][d])hist<<t<<'\t'<<d<<'\t'<<counts[t][d]<<'\n';}o<<"audit_errors\t"<<err<<"\tlegal_moves\t"<<edges<<'\n';ofstream f(nm+"_dtm.bin",ios::binary);f.write((char*)dd.data(),dd.size());ofstream g(nm+"_reach.bin",ios::binary);g.write((char*)reach5.data(),reach5.size());cerr<<"DONE "<<nm<<" errors "<<err<<" max "<<maxd[0]<<' '<<maxd[1]<<" reach3 "<<nr[0][1]<<' '<<nr[1][1]<<endl;return err!=0;}
